<template><section class="mx-auto max-w-7xl px-4 py-14 sm:px-6 lg:px-8"><p class="text-sm uppercase tracking-[.35em] text-cyan-200">Live Event Program</p><h1 class="mt-4 max-w-4xl text-5xl font-black">Two days from inspiration to working prototypes.</h1><p class="mt-5 text-lg text-slate-300">18–19 November 2026 · Jakarta Convention Center</p><div v-if="pending" class="mt-10 space-y-4"><div v-for="n in 6" :key="n" class="h-28 animate-pulse rounded-3xl bg-white/5" /></div><div v-else-if="error" class="mt-10 rounded-3xl border border-red-400/30 bg-red-950/30 p-6 text-red-100">The event schedule could not be loaded.</div><div v-else class="mt-10 space-y-10"><section v-for="day in groupedSessions" :key="day.date"><p class="text-xs uppercase tracking-[.3em] text-orange-200">{{ day.date }}</p><div class="mt-5 space-y-4"><article v-for="session in day.items" :key="session.id" class="glass-card grid gap-4 rounded-3xl p-6 sm:grid-cols-[160px_1fr]"><div><p class="font-mono text-sm text-cyan-200">{{ formatTime(session.start_at) }}–{{ formatTime(session.end_at) }}</p><p class="mt-2 text-xs uppercase tracking-[.2em] text-slate-500">{{ session.room_name }}</p></div><div><p class="text-xs uppercase tracking-[.2em] text-orange-100">{{ label(session.session_type) }}</p><h2 class="mt-2 text-xl font-bold">{{ session.title }}</h2><p class="mt-2 text-sm leading-7 text-slate-300">{{ session.description }}</p></div></article></div></section></div></section></template>
<script setup lang="ts">import {useEvent,type SessionItem} from '~/composables/useEvent'; useSeoMeta({title:'Program | ASEAN AI for Education Summit 2026',description:'Live two-day event schedule loaded from the ASEAN AI Event Portal API.'}); const {getEvents,getEventSessions}=useEvent(); const {data:response,pending,error}=await useAsyncData('public-event-sessions',async()=>{const events=await getEvents(1,1);const event=events.data[0];if(!event?.slug)throw new Error('Event not found');return getEventSessions(event.slug)}); const sessions=computed(()=>response.value?.data??[]); const groupedSessions=computed(()=>{const groups=new Map<string,SessionItem[]>();for(const item of sessions.value){const date=new Intl.DateTimeFormat('en-GB',{weekday:'long',day:'numeric',month:'long',year:'numeric',timeZone:'Asia/Jakarta'}).format(new Date(item.start_at));groups.set(date,[...(groups.get(date)??[]),item])}return [...groups].map(([date,items])=>({date,items}))}); const formatTime=(iso:string)=>new Intl.DateTimeFormat('en-GB',{hour:'2-digit',minute:'2-digit',hour12:false,timeZone:'Asia/Jakarta'}).format(new Date(iso)); const label=(value?:string)=>(value??'session').replaceAll('_',' ');</script>
